import{_ as a,o,c as i,ae as t}from"./chunks/framework.DYeE-XvM.js";const u=JSON.parse('{"title":"API 概览","description":"","frontmatter":{},"headers":[],"relativePath":"reference/api.md","filePath":"reference/api.md","lastUpdated":null}'),r={name:"reference/api.md"};function n(l,e,c,d,s,p){return o(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="api-概览" tabindex="-1">API 概览 <a class="header-anchor" href="#api-概览" aria-label="Permalink to &quot;API 概览&quot;">​</a></h1><p>服务启动后可访问 Swagger：</p><p><code>http://localhost:2567/api-docs</code></p><p>API 默认前缀为 <code>/api</code>。</p><h2 id="认证与登录" tabindex="-1">认证与登录 <a class="header-anchor" href="#认证与登录" aria-label="Permalink to &quot;认证与登录&quot;">​</a></h2><ul><li><code>POST /api/auth/login</code>：账号登录并获取 JWT</li><li><code>POST /api/auth/refresh</code>：刷新 Token</li></ul><h2 id="小游戏接口" tabindex="-1">小游戏接口 <a class="header-anchor" href="#小游戏接口" aria-label="Permalink to &quot;小游戏接口&quot;">​</a></h2><p>包括 <strong>微信小游戏登录</strong>、<strong>抖音小游戏登录接口</strong>，以及对应的 <strong><code>access_token</code></strong> 获取接口：</p><ul><li><code>GET /api/minigame/douyin/access_token</code></li><li><code>GET /api/minigame/douyin/login</code></li><li><code>GET /api/minigame/weixin/access_token</code></li><li><code>GET /api/minigame/weixin/login</code></li></ul><p>登录类接口在换取平台 <code>openid</code>（及抖音侧匿名 id 等）后，会 <strong>自动查找或创建</strong> 本地用户，响应中包含 <strong><code>token</code>（JWT）</strong> 与 <strong><code>user</code>（本地用户资料，不含密码）</strong>；JWT 中的 <strong><code>userId</code> 为数据库用户主键</strong>，与平台 openid 不同。详见教程。</p><p>教程：</p><ul><li><a href="/xcs.github.io/reference/minigame/weixin.html">微信小游戏登录教程</a></li><li><a href="/xcs.github.io/reference/minigame/douyin.html">抖音小游戏登录教程</a></li></ul><h2 id="调试建议" tabindex="-1">调试建议 <a class="header-anchor" href="#调试建议" aria-label="Permalink to &quot;调试建议&quot;">​</a></h2><ul><li>开发阶段优先通过 Swagger 调试参数。</li><li>接入 Colyseus 房间前，先获取并验证 JWT。</li></ul>',14)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
